package enrich

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"path/filepath"
	"strings"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/pack"
	"github.com/mellifera/mellifera/internal/refusal"
)

// streamsLaneID is the `__streams__` lane key (packaged-playback D-10): a
// plugin-id-like string under which the lane's lease owner and its
// enrichment_failures ledger rows are recorded. Ledger rows under this key are
// exempt from any future unregistered-plugin purge, and the lane NEVER
// participates in metadata-completion semantics (no metadata source, no
// lifecycle transition, no metadata namespace is read or written by it).
const streamsLaneID = "__streams__"

// streamsOwner is the lease owner string the lane acquires with — the same
// per-item leaseMap the metadata dispatch uses, so a pack and a metadata run
// for one item serialize exactly like two metadata sources.
const streamsOwner = "streams"

// EnqueuePack enqueues one packaging job for itemID into the running queue's
// channel (the streams lane's dispatch entry — the frontier's and the play
// verb's re-enqueue point). It returns an error when the queue is not running
// or its buffer is momentarily full; a job whose item's lease is already held
// is dropped by the driver (the in-flight run owns the item). The channel send
// is serialized against Stop's close by sendMu.
func (q *Queue) EnqueuePack(itemID string) error {
	q.sendMu.Lock()
	defer q.sendMu.Unlock()
	if !q.running.Load() {
		return errors.New("enrich: queue not running")
	}
	select {
	case q.work <- laneTask{rowID: itemID, streams: true}:
		q.statPending.Add(1)
		return nil
	default:
		return errors.New("enrich: queue buffer full")
	}
}

// laneTask is one buffered dispatch task: a row id plus its lane. The zero
// value is a metadata task (the pre-lane channel carried bare row ids).
type laneTask struct {
	rowID   string
	streams bool
}

// workStreams is the streams lane's per-item driver (the dedicated dispatch
// branch, D-10): acquire the item's lease, renew it while the packaging run
// proceeds, run the PackItem seam, and persist the outcome by REPLACING ONLY
// the document's `streams` namespace — via the lane's persist path (a fresh
// row reload immediately before the writeMu-guarded write) so a concurrent
// metadata write can never be clobbered. Terminal failure records a
// pack_failed ledger row under __streams__ (flat 30-day cooldown, no
// doubling); a refusal.PolicyRefusal — the pack gate closed after enqueue,
// playback-capability-gate D4 — branches BEFORE the ledger: it persists the
// failed state with the gate token and writes NO row, so a knob setting
// never charges the cooldown. Success clears the row (reset-on-success).
// Metadata completion —
// lifecycle states, metadata namespaces, _stages — is untouched either way.
// A lane with a nil PackItem seam is disabled: the task is a no-op.
func (q *Queue) workStreams(ctx context.Context, itemID string) {
	if q.deps.PackItem == nil {
		return // lane not armed; nothing to do
	}
	if !q.leases.acquire(itemID, streamsOwner, q.cfg.LeaseTTL) {
		return // live lease held -> the in-flight run owns this item
	}
	defer q.leases.release(itemID)
	done := make(chan struct{})
	defer close(done)
	go q.renewLease(itemID, q.cfg.LeaseTTL, done) // a long pack renews; renewal ends when the run ends
	q.statPending.Add(-1)
	q.statInFlight.Add(1)
	defer q.statInFlight.Add(-1)

	row, err := q.deps.Store.GetItem(ctx, itemID, access.System())
	if err != nil {
		return // item gone (deleted between enqueue and drain); nothing to do
	}
	doc := decodeDoc(row.Document)
	outcome, packErr := q.deps.PackItem(ctx, itemID, documentAbsolutePath(doc), docFFprobe(doc),
		documentVoiceoverPaths(doc, row.RelativePath))
	if packErr != nil {
		var policyRefusal refusal.PolicyRefusal
		if errors.As(packErr, &policyRefusal) {
			// A policy verdict (the gate closed between enqueue and build)
			// is never a pack failure: persist the honest failed state with
			// the gate token and write NO pack_failed ledger row — a knob
			// setting never charges the 30-day cooldown, and flipping the
			// knob on heals through the frontier (no ledger to clear).
			q.persistStreams(ctx, itemID, failedStreamsDoc(policyRefusal.Reason))
			return
		}
		q.recordPackFailure(ctx, itemID, packErr)
		q.persistStreams(ctx, itemID, failedStreamsDoc(packErr.Error()))
		return
	}
	q.storeWrite(func() error { // reset-on-success
		return q.deps.Store.ClearFailure(ctx, itemID, streamsLaneID)
	})
	success := map[string]any{
		"state":    "complete",
		"playlist": outcome.Playlist,
		"nonce":    outcome.Nonce,
		// The pack-lane rule version (fix-tv-unblock-2 Interfaces 2): every
		// build this lane publishes is composed at the current rule — the
		// lane-composed master at the build root since v1, the total-audio
		// layout rule since v2 — so the key is honest by construction and
		// written only here, on the success persist. The failed docs above
		// stay version-free: absence reads as version 0, the legacy signal
		// the lazy re-heal gate reads. No Build/pack.PackOutcome field, no second
		// constant — the map key carries pack.MasterRuleVersion itself.
		"master": pack.MasterRuleVersion,
	}
	if len(outcome.Codecs) > 0 {
		// The codec record rides the completion write (playback-capability-gate
		// D2); an uncomposable record (nil) stays an absent key.
		success["codecs"] = outcome.Codecs
	}
	if outcome.Layout != "" {
		// The layout record rides the completion write too (fix-tv-unblock-2
		// Interfaces 1): the lane's own layoutName decision at publish, the one
		// field the SPA's rendition refusal reads. An empty value (a build the
		// seam predates) stays an absent key — absence is the fail-open signal
		// the descriptor answers verbatim, the codecs precedent.
		success["layout"] = outcome.Layout
	}
	q.persistStreams(ctx, itemID, success)
}

// renewLease extends itemID's lease at half-TTL intervals until done closes —
// the leaseMap.renew callers the long-run story needs (a run outliving the
// TTL is never treated as dead mid-flight; renewal ends when the run ends).
func (q *Queue) renewLease(itemID string, ttl time.Duration, done <-chan struct{}) {
	if ttl <= 0 {
		return
	}
	ticker := time.NewTicker(ttl / 2)
	defer ticker.Stop()
	for {
		select {
		case <-done:
			return
		case <-ticker.C:
			q.leases.renew(itemID, ttl)
		}
	}
}

// recordPackFailure writes the terminal pack_failed ledger row under
// __streams__ with the FLAT cooldown (terminalCooldown's no-doubling branch,
// D-10). Best-effort like every ledger write: a failed write leaves the
// failure visible in the document state anyway.
func (q *Queue) recordPackFailure(ctx context.Context, itemID string, cause error) {
	prior := q.packFailAttempts(ctx, itemID)
	attempts, cool := terminalCooldown(ledgerPackFailed, prior, q.cfg)
	reason := cause.Error()
	q.storeWrite(func() error {
		return q.deps.Store.RecordFailure(ctx, itemID, streamsLaneID, ledgerPackFailed, reason, attempts, now().Add(cool))
	})
}

// packFailAttempts reads the prior pack_failed row's attempt count so the
// stored attempts increment per round (the flat shape still distinguishes
// rounds; the cooldown itself never doubles).
func (q *Queue) packFailAttempts(ctx context.Context, itemID string) int {
	rows, err := q.deps.Store.ListFailures(ctx)
	if err != nil {
		return 0
	}
	return priorAttempts(buildFailureIndex(rows), itemID, streamsLaneID)
}

// persistStreams is the lane's ONLY document-write path (Interfaces §1): it
// re-reads the item's row FRESH inside the writeMu critical section and
// replaces only doc["streams"], preserving the row's lifecycle status and
// every other document byte as loaded — a concurrent metadata write that
// landed between the run's start and here is carried, not clobbered (D-10).
func (q *Queue) persistStreams(ctx context.Context, itemID string, streams map[string]any) {
	q.storeWrite(func() error {
		row, err := q.deps.Store.GetItem(ctx, itemID, access.System())
		if err != nil {
			return fmt.Errorf("enrich: streams reload %s: %w", itemID, err)
		}
		doc := decodeDoc(row.Document)
		doc["streams"] = streams
		b, err := json.Marshal(doc)
		if err != nil {
			return fmt.Errorf("enrich: streams marshal %s: %w", itemID, err)
		}
		row.Document = b
		return q.deps.Store.PutItem(ctx, row)
	})
}

// failedStreamsDoc is the persisted failure state: state failed + the failure
// timestamp (the cooldown's display half; the authoritative cooldown lives in
// the ledger row) + the free-text reason. On the policy-refusal path reason
// is exactly the gate's state_reason token (D1 — one vocabulary); on a real
// pack failure it is the cause's message.
func failedStreamsDoc(reason string) map[string]any {
	return map[string]any{
		"state":     "failed",
		"failed_at": now().UTC().Format(time.RFC3339),
		"reason":    reason,
	}
}

// documentAbsolutePath reads parsed.absolute_path — the only file-location
// channel into any enricher chain (the stamp scan assembles; assembleBaseDoc).
// Empty when absent or unreadable.
func documentAbsolutePath(doc map[string]any) string {
	parsed, ok := doc["parsed"].(map[string]any)
	if !ok {
		return ""
	}
	p, _ := parsed["absolute_path"].(string)
	return p
}

// documentVoiceoverPaths derives the absolute paths of the item's
// episode-linked AUDIO sidecars, in document order — the pack seam's rendition
// facts (serial-watch-flow D-2). The library root comes from the episode's own
// stored facts (parsed.absolute_path minus the row's relative_path, the exact
// derivation internal/api's sidecarMediaPath uses so serving and packing
// agree, D-4) joined with the sidecar's stored relative path; a path is never
// taken from client input. Subtitle sidecars and serial-level sidecars
// (parsed.series_sidecars) are not episode-linked voiceovers and never pass.
// Nil when the document carries no audio sidecars.
func documentVoiceoverPaths(doc map[string]any, relPath string) []string {
	parsed, ok := doc["parsed"].(map[string]any)
	if !ok {
		return nil
	}
	abs, _ := parsed["absolute_path"].(string)
	raw, _ := parsed["sidecars"].([]any)
	var out []string
	for _, c := range raw {
		sc, ok := c.(map[string]any)
		if !ok {
			continue
		}
		if kind, _ := sc["kind"].(string); kind != "audio" {
			continue
		}
		rel, _ := sc["relative_path"].(string)
		out = append(out, filepath.Join(strings.TrimSuffix(abs, relPath), rel))
	}
	return out
}

// docFFprobe returns the document's stored ffprobe facts as a map (the pack
// seam's duration source). Nil when absent or unreadable.
func docFFprobe(doc map[string]any) map[string]any {
	m, ok := doc["ffprobe"].(map[string]any)
	if !ok {
		return nil
	}
	return m
}
